CREATE TABLE `deployment_releases` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`stage` ENUM('S0','S1','S2') NOT NULL,`app_version` VARCHAR(80) NOT NULL,`build_sha` VARCHAR(80) CHARACTER SET ascii NOT NULL,`config_fingerprint` CHAR(64) CHARACTER SET ascii NOT NULL,`migration_version` VARCHAR(180) NOT NULL,`status` ENUM('planned','preflight_passed','deploying','healthy','failed','rolled_back') NOT NULL,`approved_by` CHAR(36) CHARACTER SET ascii NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`started_at` DATETIME(3) NULL,`finished_at` DATETIME(3) NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_deployment_build_stage` (`stage`,`build_sha`),KEY `idx_deployment_status_updated` (`status`,`updated_at`),KEY `idx_deployment_trace` (`trace_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
